#include <iostream>
#include <vector>
#include <algorithm>

template <typename T>
T findMax(const T& a, const T& b) {
    return (a > b) ? a : b;
}

int main() {
    int a = 5, b = 10;
    double x = 3.14, y = 2.71;
    std::cout << "Max of " << a << " and " << b << " is " << findMax(a, b) << std::endl;
    std::cout << "Max of " << x << " and " << y << " is " << findMax(x, y) << std::endl;
    return 0;
}
